Console.WriteLine("\n=== CSC TASKS ===");
foreach (var task in build.FindChildrenRecursive<Task>().Where(t => t.Name == "Csc"))
{
    var proj = task.GetNearestParent<Project>()?.Name ?? "?";
    Console.WriteLine($"Csc in {proj}");
    foreach (var msg in task.FindChildrenRecursive<Message>().Take(5))
    {
        Console.WriteLine($"  msg: {msg.Text?.Substring(0, Math.Min(200, msg.Text?.Length ?? 0))}");
    }
}

// Check if Api.csproj compilation was attempted
Console.WriteLine("\n=== API BUILD TARGETS ===");
foreach (var proj in build.FindChildrenRecursive<Project>().Where(p => p.Name == "Api.csproj"))
{
    var hasCompile = proj.FindChildrenRecursive<Target>().Any(t => t.Name == "CoreCompile");
    var hasBuildErr = proj.FindChildrenRecursive<Error>().Any();
    Console.WriteLine($"Api.csproj instance - CoreCompile attempted: {hasCompile}, HasErrors: {hasBuildErr}");
    foreach (var err in proj.FindChildrenRecursive<Error>())
    {
        Console.WriteLine($"  Error: {err.Code} {err.Text}");
    }
}
EOF

